/*
 * font.h - the built-in 8x16 font of the test kernel.
 *
 * The glyph data (font8x16.c) is generated by scripts/gen_font.py from a
 * system font. Printable ASCII only (0x20 to 0x7E). Test code only.
 */

#ifndef JUSTOS_TESTS_QEMU_TEST_KERNEL_FONT_H
#define JUSTOS_TESTS_QEMU_TEST_KERNEL_FONT_H

#include <stdint.h>

#define JP_TEST_FONT_WIDTH 8
#define JP_TEST_FONT_HEIGHT 16
#define JP_TEST_FONT_FIRST_CHAR 0x20
#define JP_TEST_FONT_LAST_CHAR 0x7E
#define JP_TEST_FONT_GLYPH_COUNT (JP_TEST_FONT_LAST_CHAR - JP_TEST_FONT_FIRST_CHAR + 1)

/* Row y of glyph (c - FIRST_CHAR): bit 7 is the leftmost pixel. */
extern const uint8_t jp_test_font8x16[JP_TEST_FONT_GLYPH_COUNT][JP_TEST_FONT_HEIGHT];

#endif /* JUSTOS_TESTS_QEMU_TEST_KERNEL_FONT_H */
